/**
 * Which formatting controls this document's format can spell — the toolbar's
 * enabled state, one flag per button, from [`LeafDoc::capabilities`]. Mirrors
 * [`leaf_core::Capabilities`], where the reasoning lives.
 *
 * Its shape is a flat record of `Bool`s rather than a query taking a gesture
 * because the Swift side wants exactly one crossing and a value it can hold in
 * an `@Observable`: `let caps = doc.capabilities()`, then
 * `.disabled(!caps.bold)` on each control.
 */
public struct Capabilities {
    public var bold: Bool
    public var italic: Bool
    public var code: Bool
    public var mark: Bool
    public var underline: Bool
    public var strike: Bool
    /**
     * [`LeafDoc::set_mark_color`] — the highlight *palette*, which Markdown
     * spells and djot does not, though both spell the highlight itself. Gate
     * the swatches on this *and* on [`LeafDoc::caret_in_mark`], the way the grid
     * controls take `table` and `caret_in_table`: one is a fact about the
     * format, the other about where the caret is standing.
     */
    public var markColor: Bool
    public var superscript: Bool
    public var `subscript`: Bool
    /**
     * Both [`LeafDoc::set_heading`] and [`LeafDoc::set_paragraph`] — they are
     * the same gesture in core and stand or fall together.
     */
    public var heading: Bool
    public var blockquote: Bool
    public var bulletList: Bool
    public var orderedList: Bool
    /**
     * [`LeafDoc::toggle_task_item`], [`LeafDoc::toggle_task_checked`] and
     * [`LeafDoc::toggle_task_at`] — including a *tap* on a rendered checkbox,
     * which should not be live where the box cannot be spelled.
     */
    public var task: Bool
    public var link: Bool
    /**
     * [`LeafDoc::insert_image`] and [`LeafDoc::insert_media`] both.
     */
    public var image: Bool
    public var thematicBreak: Bool
    /**
     * [`LeafDoc::insert_footnote`]. Markdown and djot spell the pair; HTML does
     * not, so the button goes rather than dims into a refusal.
     */
    public var footnote: Bool
    public var codeLanguage: Bool
    /**
     * The grid controls. Gate them on this *and* [`LeafDoc::caret_in_table`]:
     * this asks whether the format's tables are editable, that whether the
     * caret is in one.
     */
    public var table: Bool
    /**
     * Shift+Return inside a cell — [`LeafDoc::cell_line_break`].
     */
    public var cellLineBreak: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(bold: Bool, italic: Bool, code: Bool, mark: Bool, underline: Bool, strike: Bool, 
        /**
         * [`LeafDoc::set_mark_color`] — the highlight *palette*, which Markdown
         * spells and djot does not, though both spell the highlight itself. Gate
         * the swatches on this *and* on [`LeafDoc::caret_in_mark`], the way the grid
         * controls take `table` and `caret_in_table`: one is a fact about the
         * format, the other about where the caret is standing.
         */markColor: Bool, superscript: Bool, `subscript`: Bool, 
        /**
         * Both [`LeafDoc::set_heading`] and [`LeafDoc::set_paragraph`] — they are
         * the same gesture in core and stand or fall together.
         */heading: Bool, blockquote: Bool, bulletList: Bool, orderedList: Bool, 
        /**
         * [`LeafDoc::toggle_task_item`], [`LeafDoc::toggle_task_checked`] and
         * [`LeafDoc::toggle_task_at`] — including a *tap* on a rendered checkbox,
         * which should not be live where the box cannot be spelled.
         */task: Bool, link: Bool, 
        /**
         * [`LeafDoc::insert_image`] and [`LeafDoc::insert_media`] both.
         */image: Bool, thematicBreak: Bool, 
        /**
         * [`LeafDoc::insert_footnote`]. Markdown and djot spell the pair; HTML does
         * not, so the button goes rather than dims into a refusal.
         */footnote: Bool, codeLanguage: Bool, 
        /**
         * The grid controls. Gate them on this *and* [`LeafDoc::caret_in_table`]:
         * this asks whether the format's tables are editable, that whether the
         * caret is in one.
         */table: Bool, 
        /**
         * Shift+Return inside a cell — [`LeafDoc::cell_line_break`].
         */cellLineBreak: Bool) {
        self.bold = bold
        self.italic = italic
        self.code = code
        self.mark = mark
        self.underline = underline
        self.strike = strike
        self.markColor = markColor
        self.superscript = superscript
        self.`subscript` = `subscript`
        self.heading = heading
        self.blockquote = blockquote
        self.bulletList = bulletList
        self.orderedList = orderedList
        self.task = task
        self.link = link
        self.image = image
        self.thematicBreak = thematicBreak
        self.footnote = footnote
        self.codeLanguage = codeLanguage
        self.table = table
        self.cellLineBreak = cellLineBreak
    }
}



extension Capabilities: Equatable, Hashable {
    public static func ==(lhs: Capabilities, rhs: Capabilities) -> Bool {
        if lhs.bold != rhs.bold {
            return false
        }
        if lhs.italic != rhs.italic {
            return false
        }
        if lhs.code != rhs.code {
            return false
        }
        if lhs.mark != rhs.mark {
            return false
        }
        if lhs.underline != rhs.underline {
            return false
        }
        if lhs.strike != rhs.strike {
            return false
        }
        if lhs.markColor != rhs.markColor {
            return false
        }
        if lhs.superscript != rhs.superscript {
            return false
        }
        if lhs.`subscript` != rhs.`subscript` {
            return false
        }
        if lhs.heading != rhs.heading {
            return false
        }
        if lhs.blockquote != rhs.blockquote {
            return false
        }
        if lhs.bulletList != rhs.bulletList {
            return false
        }
        if lhs.orderedList != rhs.orderedList {
            return false
        }
        if lhs.task != rhs.task {
            return false
        }
        if lhs.link != rhs.link {
            return false
        }
        if lhs.image != rhs.image {
            return false
        }
        if lhs.thematicBreak != rhs.thematicBreak {
            return false
        }
        if lhs.footnote != rhs.footnote {
            return false
        }
        if lhs.codeLanguage != rhs.codeLanguage {
            return false
        }
        if lhs.table != rhs.table {
            return false
        }
        if lhs.cellLineBreak != rhs.cellLineBreak {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(bold)
        hasher.combine(italic)
        hasher.combine(code)
        hasher.combine(mark)
        hasher.combine(underline)
        hasher.combine(strike)
        hasher.combine(markColor)
        hasher.combine(superscript)
        hasher.combine(`subscript`)
        hasher.combine(heading)
        hasher.combine(blockquote)
        hasher.combine(bulletList)
        hasher.combine(orderedList)
        hasher.combine(task)
        hasher.combine(link)
        hasher.combine(image)
        hasher.combine(thematicBreak)
        hasher.combine(footnote)
        hasher.combine(codeLanguage)
        hasher.combine(table)
        hasher.combine(cellLineBreak)
    }
}


