/**
 * One `{key=value}` attribute of a [`DirectiveView`]. A record rather than a
 * tuple because UniFFI has no tuple type; an absent value flattens to `""`,
 * since a bare attribute is a flag and the distinction from `key=""` has no
 * consumer on this side.
 */
public struct DirectiveAttr {
    public var key: String
    public var value: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(key: String, value: String) {
        self.key = key
        self.value = value
    }
}



extension DirectiveAttr: Equatable, Hashable {
    public static func ==(lhs: DirectiveAttr, rhs: DirectiveAttr) -> Bool {
        if lhs.key != rhs.key {
            return false
        }
        if lhs.value != rhs.value {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(key)
        hasher.combine(value)
    }
}


