        return
            try DirectiveAttr(
                key: FfiConverterString.read(from: &buf), 
                value: FfiConverterString.read(from: &buf)
        )
    }

    public static func write(_ value: DirectiveAttr, into buf: inout [UInt8]) {
        FfiConverterString.write(value.key, into: &buf)
